  sim: { ambient: 12, engT: 12 }, garage: { engT: 12 }, start: { cold: 'startLong', hot: 'start' },
  codes: [],
  road: [['scene', { sky: 'day' }], ['say', T('Filtrul de motorină a fost schimbat acum o lună.', 'The fuel filter was changed a month ago.')], ['btn', T('Răsucește cheia', 'Turn the key')], ['start', 'startLong'], ['say', T('Învârte 5 secunde până prinde.', 'Cranks 5 seconds before catching.')], ['btn', 'toGarage'], ['park']],
  fuel: T('În furtunul transparent dinaintea pompei apar bule. Conducta de retur de la filtru e montată crăpată la colier.', 'Bubbles appear in the clear hose before the pump. The filter return line is cracked at its clip.'),
