  drive: { txt: T('Fum negru la accelerare, consum mare.', 'Black smoke accelerating, high consumption.'), smoke: 'black' },
  listen: T('Un injector bate mai tare decât celelalte (cilindrul 2).', 'One injector knocks louder than the others (cylinder 2).'), listenSfx: 'knock',
